const GLOBAL_STYLE = `
  @import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;500;700&display=swap');

  * { font-family: 'Inter', sans-serif; }

  .room-hitbox {
    transition: fill 0.1s ease;
  }
  .room-hitbox:hover {
    fill: rgba(0,0,0,0.12);
  }
  .room-hitbox:active {
    fill: rgba(0,0,0,0.28);
  }
`;

function PageHeader({ title, onBack }) {
  return (
    <div
      style={{
        position: "fixed",
        top: 0,
        left: 0,
        right: 0,
        height: "70px",
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
        zIndex: 10,
        pointerEvents: "none",
      }}
    >
      <button
        onClick={onBack}
        style={{
          position: "absolute",
          left: "24px",
          top: "50%",
          transform: "translateY(-50%)",
          background: "none",
          border: "none",
          padding: 0,
          cursor: "pointer",
          pointerEvents: "auto",
        }}
      >
        <svg width="16" height="34" viewBox="0 0 14 30" style={{ display: "block" }}>
          <path d="M14 0L0 15L14 30Z" fill="black" />
        </svg>
      </button>
      <div style={{ fontWeight: "bold", fontSize: "24px", color: "black" }}>{title}</div>
    </div>
  );
}

function LandingPage({ onSelectHouse }) {
  return (
    <div style={{ width: "100%", height: "100vh", background: "#ffffff", display: "flex", alignItems: "center", justifyContent: "center" }}>
      <div style={{ display: "flex", gap: "80px" }}>
        {[1, 2].map((n) => (
          <button
            key={n}
            onClick={() => onSelectHouse(n)}
            style={{ background: "none", border: "none", cursor: "pointer", display: "flex", flexDirection: "column", alignItems: "center", gap: "12px" }}
          >
            <div style={{ fontSize: "64px" }}>🏠</div>
            <div style={{ fontWeight: "bold", fontSize: "18px", color: "#000" }}>House {n}</div>
          </button>
        ))}
      </div>
    </div>
  );
}

function MapPage({ house, onSelectRoom, onBack }) {
  const [isMobile, setIsMobile] = React.useState(window.innerWidth < 768);

  React.useEffect(() => {
    const handleResize = () => setIsMobile(window.innerWidth < 768);
    window.addEventListener("resize", handleResize);
    return () => window.removeEventListener("resize", handleResize);
  }, []);

  const svgMarkup = isMobile ? (house === 1 ? SVG_HOUSE_1_MOBILE : SVG_HOUSE_2_MOBILE) : (house === 1 ? SVG_HOUSE_1 : SVG_HOUSE_2);

  function handleClick(e) {
    const target = e.target.closest("[data-room]");
    if (!target) return;
    let roomId = target.dataset.room;
    
    // jade kitchen: 두 부분이 하나로 동작 (한쪽 클릭시 다른쪽도 함께 활성화)
    if (roomId === "h2-kitchen-large" || roomId === "h2-kitchen-small") {
      // 두 부분 모두에 활성화 효과 주기
      document.querySelectorAll('[data-room="h2-kitchen-large"], [data-room="h2-kitchen-small"]').forEach(rect => {
        rect.style.fill = "rgba(0,0,0,0.28)";
      });
      roomId = "h2-kitchen";
    }
    
    onSelectRoom(roomId);
  }

  const headerHeight = isMobile ? "50px" : "70px";
  const headerFontSize = isMobile ? "18px" : "24px";
  const mapMaxWidth = isMobile ? "90vw" : "65vw";
  const mapMaxHeight = isMobile ? "92vh" : "85vh";

  return (
    <div style={{ width: "100vw", height: "100vh", background: "#fff", display: "flex", alignItems: "center", justifyContent: "center", overflow: "hidden" }}>
      <div
        style={{
          position: "fixed",
          top: 0,
          left: 0,
          right: 0,
          height: headerHeight,
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          zIndex: 10,
          pointerEvents: "none",
        }}
      >
        <button
          onClick={onBack}
          style={{
            position: "absolute",
            left: "24px",
            top: "50%",
            transform: "translateY(-50%)",
            background: "none",
            border: "none",
            padding: 0,
            cursor: "pointer",
            pointerEvents: "auto",
          }}
        >
          <svg width="16" height="34" viewBox="0 0 14 30" style={{ display: "block" }}>
            <path d="M14 0L0 15L14 30Z" fill="black" />
          </svg>
        </button>
        <div style={{ fontWeight: "bold", fontSize: headerFontSize, color: "black" }}>{`House ${house}`}</div>
      </div>
      <div
        className="map-scale-wrap"
        onClick={handleClick}
        dangerouslySetInnerHTML={{ __html: svgMarkup }}
      />
      <style>{`
        .map-scale-wrap svg { max-width: ${mapMaxWidth}; max-height: ${mapMaxHeight}; width: auto; height: auto; display: block; transform: ${isMobile ? (house === 1 ? "scale(1.35)" : "scale(1.6)") : "scale(1)"}; transform-origin: center; }
      `}</style>
    </div>
  );
}

function ArchivePage({ roomId, onBack }) {
  const room = ROOMS[roomId];
  if (!room) return null;

  const [isMobile, setIsMobile] = React.useState(window.innerWidth < 768);

  React.useEffect(() => {
    const handleResize = () => setIsMobile(window.innerWidth < 768);
    window.addEventListener("resize", handleResize);
    return () => window.removeEventListener("resize", handleResize);
  }, []);

  const headerHeight = isMobile ? "50px" : "70px";
  const headerFontSize = isMobile ? "18px" : "24px";
  const paddingTop = isMobile ? "70px" : "90px";

  return (
    <div style={{ width: "100%", minHeight: "100vh", background: "#fff", boxSizing: "border-box" }}>
      <div
        style={{
          position: "fixed",
          top: 0,
          left: 0,
          right: 0,
          height: headerHeight,
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          zIndex: 10,
          pointerEvents: "none",
          background: "#fff",
        }}
      >
        <button
          onClick={onBack}
          style={{
            position: "absolute",
            left: "24px",
            top: "50%",
            transform: "translateY(-50%)",
            background: "none",
            border: "none",
            padding: 0,
            cursor: "pointer",
            pointerEvents: "auto",
          }}
        >
          <svg width="16" height="34" viewBox="0 0 14 30" style={{ display: "block" }}>
            <path d="M14 0L0 15L14 30Z" fill="black" />
          </svg>
        </button>
        <div style={{ fontWeight: "bold", fontSize: headerFontSize, color: "black" }}>{room.label}</div>
      </div>
      <div style={{ paddingTop, paddingLeft: "20px", paddingRight: "20px" }}>
        <div style={{ display: "flex", gap: "16px", overflowX: "auto", paddingBottom: "20px" }}>
          {room.photos.length === 0 ? (
            <div style={{ width: "100%", height: "300px", display: "flex", alignItems: "center", justifyContent: "center", background: "#f0f0f0", color: "#999" }}>
              아직 업로드된 사진이 없어요
            </div>
          ) : (
            room.photos.map((src, i) => (
              <img key={i} src={src} style={{ height: "70vh", flexShrink: 0, objectFit: "cover" }} alt={`${room.label} ${i + 1}`} />
            ))
          )}
        </div>
      </div>
    </div>
  );
}

export default function App() {
  const [view, setView] = useState({ type: "landing" });

  return (
    <>
      <style>{GLOBAL_STYLE}</style>

      {view.type === "landing" && (
        <LandingPage onSelectHouse={(house) => setView({ type: "map", house })} />
      )}

      {view.type === "map" && (
        <MapPage
          house={view.house}
          onSelectRoom={(roomId) => setView({ type: "archive", roomId, house: view.house })}
          onBack={() => setView({ type: "landing" })}
        />
      )}

      {view.type === "archive" && (
        <ArchivePage
          roomId={view.roomId}
          onBack={() => setView({ type: "map", house: view.house })}
        />
      )}
    </>
  );
}
